function formatCurrentDate(date = new Date()) { return new Intl.DateTimeFormat('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' }).format(date).toUpperCase(); }
function updateCurrentDate() {
  const now = new Date();
  const date = document.querySelector('#currentDate');
  if (date) date.textContent = formatCurrentDate(now);
  const weekLabel = document.querySelector('#termWeek');
  const progress = document.querySelector('.progress-track span');
  if (!weekLabel || !progress) return;
  const firstWeek = new Date(2026, 7, 3);
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const elapsedWeeks = Math.floor((today - firstWeek) / (7 * 24 * 60 * 60 * 1000));
  const week = Math.min(18, Math.max(1, elapsedWeeks + 1));
  weekLabel.textContent = `Week ${String(week).padStart(2, '0')}`;
  progress.style.width = `${(week / 18) * 100}%`;
}

