const paymentLogoUrls = {
  'logo-rcbc': 'https://www.google.com/s2/favicons?domain=rcbc.com&sz=64',
  'logo-landbank': 'https://www.google.com/s2/favicons?domain=landbank.com&sz=64',
  'logo-maya': 'https://www.google.com/s2/favicons?domain=maya.ph&sz=64',
  'logo-cebuana': 'https://www.google.com/s2/favicons?domain=cebuanalhuillier.com&sz=64',
  'logo-gcash': 'https://www.google.com/s2/favicons?domain=gcash.com&sz=64',
  'logo-bukas': 'https://www.google.com/s2/favicons?domain=bukas.ph&sz=64',
};

function enhancePaymentLogos() {
  document.querySelectorAll('.payment-logo').forEach((logo) => {
    const logoClass = Object.keys(paymentLogoUrls).find((className) => logo.classList.contains(className));
    if (!logoClass || logoClass === 'logo-cebuana' || logo.querySelector('img')) return;
    const image = document.createElement('img');
    image.src = paymentLogoUrls[logoClass];
    image.alt = '';
    image.loading = 'lazy';
    image.onerror = () => image.remove();
    logo.replaceChildren(image);
  });
}

function showToast(message) { toast.textContent = message; toast.classList.add('show'); window.clearTimeout(showToast.timeout); showToast.timeout = window.setTimeout(() => toast.classList.remove('show'), 2600); }
function bindActions() {
  enhancePaymentLogos();
  document.querySelectorAll('[data-toast]').forEach((button) => button.addEventListener('click', () => showToast(button.dataset.toast)));
  const helpButton = document.querySelector('#helpButton');
  if (helpButton) helpButton.addEventListener('click', () => showToast('Help Center is coming right up.'));
  document.querySelectorAll('form').forEach((form) => form.addEventListener('submit', (event) => {
    event.preventDefault();
    showToast('Changes saved successfully.');
  }));
  document.querySelectorAll('.term-switch button').forEach((button) => button.addEventListener('click', () => {
    const group = button.parentElement;
    group.querySelectorAll('button').forEach((termButton) => termButton.classList.remove('active'));
    button.classList.add('active');
    showToast(`${button.textContent} schedule selected.`);
  }));
  document.querySelectorAll('.curriculum-tabs button,.year-links button').forEach((button) => button.addEventListener('click', () => {
    const group = button.parentElement;
    group.querySelectorAll('button').forEach((item) => item.classList.remove('active'));
    button.classList.add('active');
    if (button.closest('.curriculum-tabs')) {
      const curriculum = button.closest('main');
      const panel = curriculum.querySelector('#curriculumPanel');
      const tabName = button.textContent.trim();
      const selectedYear = curriculum.querySelector('.curriculum-year-select')?.value || '2026 - 2027';
      group.querySelectorAll('button').forEach((item) => item.setAttribute('aria-selected', String(item === button)));
      if (panel) panel.innerHTML = selectedYear === '2026 - 2027' && curriculumTabs[tabName] ? curriculumTabs[tabName] : curriculumYearView(selectedYear);
    }
  }));
  document.querySelectorAll('.grade-year-select').forEach((select) => select.addEventListener('change', () => {
    const page = select.closest('.content');
    const panel = page.querySelector('.grade-history-panel');
    const activeTerm = page.querySelector('.grade-term-tabs button.active')?.dataset.term || 'Term 1';
    if (panel) panel.innerHTML = gradeTermView(select.value, activeTerm);
  }));
  document.querySelectorAll('.grade-term-tabs button').forEach((button) => button.addEventListener('click', () => {
    const page = button.closest('.content');
    const select = page.querySelector('.grade-year-select');
    page.querySelectorAll('.grade-term-tabs button').forEach((item) => item.classList.toggle('active', item === button));
    const panel = page.querySelector('.grade-history-panel');
    if (panel) panel.innerHTML = gradeTermView(select.value, button.dataset.term);
  }));
  document.querySelectorAll('.curriculum-year-select').forEach((select) => select.addEventListener('change', () => {
    const page = select.closest('.content');
    const panel = page.querySelector('#curriculumPanel');
    if (panel) panel.innerHTML = curriculumYearView(select.value);
  }));
  document.querySelectorAll('.mobile-day-button').forEach((button) => button.addEventListener('click', () => {
    const schedule = button.closest('.content');
    const day = button.dataset.day;
    schedule.querySelectorAll('.mobile-day-button').forEach((item) => item.classList.toggle('active', item === button));
    schedule.querySelectorAll('.mobile-day').forEach((item) => item.classList.toggle('active', item.dataset.day === day));
  }));
  document.querySelectorAll('.schedule-full-view-toggle').forEach((button) => button.addEventListener('click', () => {
    const schedule = button.closest('.page-heading')?.nextElementSibling?.parentElement || button.closest('main');
    const shell = button.closest('.content');
    const fullView = shell?.classList.toggle('schedule-full-view');
    button.setAttribute('aria-expanded', String(Boolean(fullView)));
    button.querySelector('span:last-child').textContent = fullView ? 'Day view' : 'Full view';
  }));
  const statement = document.querySelector('.soa-table');
  if (statement) {
    const total = statement.querySelector('.table-total .amount');
    statement.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => checkbox.addEventListener('change', () => {
      const selectedAmount = [...statement.querySelectorAll('input[type="checkbox"]:checked')].reduce((sum, item) => {
        const amount = item.closest('tr').querySelector('.amount').textContent.replace(/[^0-9.]/g, '');
        return sum + Number.parseFloat(amount || 0);
      }, 0);
      total.textContent = `₱ ${selectedAmount.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }));
  }
}
function setActiveLink(hash) { document.querySelectorAll('.nav-link').forEach((link) => { const active = link.getAttribute('href') === hash || (hash === '#dashboard' && link.getAttribute('href') === '#dashboard'); link.classList.toggle('active', active); if (active) { const group = link.closest('.nav-group'); if (group) setSectionState(group, true); } }); }
function setSectionState(group, isOpen) { group.classList.toggle('collapsed', !isOpen); const toggle = group.querySelector('.section-toggle'); if (toggle) toggle.setAttribute('aria-expanded', String(isOpen)); }
function initSectionToggles() { document.querySelectorAll('.nav-group').forEach((group, index) => { const toggle = group.querySelector('.section-toggle'); if (!toggle) return; const savedState = window.localStorage.getItem(`mymapua-section-v2-${index}`); setSectionState(group, savedState === 'open'); toggle.addEventListener('click', () => { const isOpen = group.classList.contains('collapsed'); document.querySelectorAll('.nav-group').forEach((otherGroup) => setSectionState(otherGroup, false)); setSectionState(group, isOpen); document.querySelectorAll('.nav-group').forEach((otherGroup, otherIndex) => window.localStorage.setItem(`mymapua-section-v2-${otherIndex}`, otherGroup === group && isOpen ? 'open' : 'closed')); }); }); }
function initTheme() { const themeToggle = document.querySelector('#themeToggle'); const savedTheme = window.localStorage.getItem('mymapua-theme'); const isDark = savedTheme === 'dark'; const updateThemeControl = (dark) => { document.documentElement.dataset.theme = dark ? 'dark' : 'light'; themeToggle.setAttribute('aria-pressed', String(dark)); themeToggle.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode'); themeToggle.querySelector('.theme-label').textContent = dark ? 'Dark mode' : 'Light mode'; }; updateThemeControl(isDark); themeToggle.addEventListener('click', () => { const nextIsDark = document.documentElement.dataset.theme !== 'dark'; window.localStorage.setItem('mymapua-theme', nextIsDark ? 'dark' : 'light'); updateThemeControl(nextIsDark); }); }
function renderPage() { const requestedHash = window.location.hash || '#dashboard'; const hash = requestedHash === '#personal' ? '#contact' : requestedHash; const page = pageData[hash]; if (!page) { pageTitle.textContent = 'My Home'; content.innerHTML = dashboardView; footer.hidden = false; setActiveLink('#dashboard'); bindActions(); updateCurrentDate(); return; } pageTitle.textContent = page[0]; content.innerHTML = `<section class="page-heading">${page[1]}</section>${page[2]}`; footer.hidden = false; setActiveLink(hash); bindActions(); updateCurrentDate(); window.scrollTo({ top: 0, behavior: 'smooth' }); }

